(()=>{"use strict";self.onmessage=async e=>{const{id:t,...o}=e.data;for(const e of Object.keys(o))self[e]=o[e];if("complete"!==o.type)try{let e;if(t<0){const t=self.pyodide,o=t.replace(/\/[^/]*$/,"/");await import(t),self.pyodide=await loadPyodide({indexURL:o}),await self.pyodide.loadPackage("micropip"),e=await self.pyodide.runPythonAsync("\n      import micropip\n      from js import packages, optlite\n      await micropip.install(optlite)\n      for p in packages:\n          await micropip.install(p)\n      "),self.pyodide.loadPackage("jedi").then(()=>{self.pyodide.runPython('import jedi; jedi.Script("str.").complete()')}).catch(()=>{})}else await self.pyodide.loadPackagesFromImports(self.script),e=await self.pyodide.runPythonAsync("\n      import optlite\n      from js import script, rawInputLst\n      optlite.exec_script(script, rawInputLst)\n      ");self.postMessage({results:e,id:t})}catch(e){self.postMessage({error:"Failed to run code: "+e.message,id:t})}else try{self._cm_complete||(await self.pyodide.loadPackage("jedi"),self.pyodide.runPython("\nimport jedi, json\ndef _cm_complete(code, line, column):\n    try:\n        return json.dumps([{'name': x.name, 'type': x.type}\n                for x in jedi.Script(code).complete(line=line, column=column)])\n    except Exception:\n        return '[]'\n"),self._cm_complete=self.pyodide.globals.get("_cm_complete"),self.jediReady=!0);const{code:e,line:s,column:i}=o,p=JSON.parse(self._cm_complete(e,s,i)||"[]");self.postMessage({suggestions:p,id:t})}catch(e){self.postMessage({error:"completion failed: "+e.message,id:t})}}})();